import os, sys, subprocess, re, datetime, pathlib
from onefetch_data import LANGUAGES_INFO, EXT_MAP

def run_git(repo_dir, args):
    cmd = ['git', '-C', repo_dir] + args
    res = subprocess.run(cmd, capture_output=True, text=True)
    if res.returncode != 0:
        return None
    return res.stdout.strip()

def format_size(num_bytes):
    if num_bytes < 1024:
        return f"{num_bytes} B"
    elif num_bytes < 1024 * 1024:
        return f"{num_bytes / 1024:.2f} KiB"
    elif num_bytes < 1024 * 1024 * 1024:
        return f"{num_bytes / (1024 * 1024):.2f} MiB"
    else:
        return f"{num_bytes / (1024 * 1024 * 1024):.2f} GiB"

def relative_time(dt_utc):
    now = datetime.datetime.now(datetime.timezone.utc)
    diff = int((now - dt_utc).total_seconds())
    if diff < 0:
        diff = 0
    if diff < 60:
        return "now"
    minutes = diff // 60
    if minutes < 60:
        return "1 minute ago" if minutes == 1 else f"{minutes} minutes ago"
    hours = minutes // 60
    if hours < 24:
        return "1 hour ago" if hours == 1 else f"{hours} hours ago"
    days = hours // 24
    if days < 14:
        return "1 day ago" if days == 1 else f"{days} days ago"
    weeks = days // 7
    if weeks < 8:
        return "1 week ago" if weeks == 1 else f"{weeks} weeks ago"
    months = days // 30
    if months < 12:
        return "1 month ago" if months == 1 else f"{months} months ago"
    years = days // 365
    return "1 year ago" if years == 1 else f"{years} years ago"

def parse_iso_time(timestamp_str):
    try:
        ts = int(timestamp_str)
        dt = datetime.datetime.fromtimestamp(ts, tz=datetime.timezone.utc)
        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")
    except:
        return ""

class RepoInfo:
    def __init__(self, config):
        self.config = config
        self.path = os.path.abspath(config.input_path)

        # Verify directory
        if not os.path.exists(self.path) or not os.path.isdir(self.path):
            sys.stderr.write(f"Error: Failed to access a directory, or path is not a directory: '{config.input_path}'\n")
            sys.exit(1)

        # Verify git repo
        git_dir = run_git(self.path, ['rev-parse', '--git-dir'])
        if git_dir is None:
            sys.stderr.write(f"Error: Could not find a git repository in '{config.input_path}' or in any of its parents\n")
            sys.exit(1)

        # Check if repo has commits
        head_commit = run_git(self.path, ['rev-parse', 'HEAD'])
        if head_commit is None:
            # Check default branch name
            branch = run_git(self.path, ['symbolic-ref', '--short', 'HEAD']) or 'master'
            sys.stderr.write(f"Error: Failed to traverse Git commit history\n\nCaused by:\n    Branch 'refs/heads/{branch}' does not have any commits\n")
            sys.exit(1)

        self.get_title()
        self.get_project()
        self.get_head()
        self.get_pending()
        self.get_commits_and_authors()
        self.get_churn()
        self.get_url()
        self.get_package_and_license()
        self.get_languages_and_loc()

    def get_title(self):
        uname = run_git(self.path, ['config', 'user.name'])
        if not uname:
            uname = run_git(self.path, ['config', 'user.email'])
        self.git_username = uname or ""

        gver = run_git(self.path, ['--version']) or "git version 2.34.1"
        self.git_version = gver

    def get_project(self):
        url = run_git(self.path, ['config', '--get', 'remote.origin.url']) or ""
        repo_name = ""
        if url:
            m = re.search(r'[:/]([^/]+?)(?:\.git)?$', url)
            if m:
                repo_name = m.group(1)
        self.repo_name = repo_name

        # Remote branches
        remotes = run_git(self.path, ['for-each-ref', '--format=%(refname)', 'refs/remotes/'])
        num_branches = 0
        if remotes:
            lines = [r for r in remotes.split('\n') if r and not r.endswith('/HEAD')]
            num_branches = len(lines)
        self.number_of_branches = num_branches

        # Tags
        tags = run_git(self.path, ['tag'])
        num_tags = len(tags.split('\n')) if tags else 0
        self.number_of_tags = num_tags

    def get_head(self):
        short_id = run_git(self.path, ['rev-parse', '--short', 'HEAD']) or ""
        self.short_commit_id = short_id

        refs_raw = run_git(self.path, ['for-each-ref', '--points-at=HEAD', '--format=%(refname:short)'])
        refs = []
        if refs_raw:
            refs = [r for r in refs_raw.split('\n') if r and not r.startswith('origin/')]
        if not refs:
            branch = run_git(self.path, ['rev-parse', '--abbrev-ref', 'HEAD'])
            if branch and branch != 'HEAD':
                refs = [branch]
        self.head_refs = refs

    def get_pending(self):
        status = run_git(self.path, ['status', '--porcelain'])
        added = 0
        deleted = 0
        modified = 0
        if status:
            for line in status.split('\n'):
                if not line: continue
                st = line[:2]
                if '?' in st or 'A' in st:
                    added += 1
                elif 'D' in st:
                    deleted += 1
                elif 'M' in st or 'R' in st:
                    modified += 1
        self.pending_added = added
        self.pending_deleted = deleted
        self.pending_modified = modified

    def get_commits_and_authors(self):
        log_args = ['log', '--format=%H|%an|%ae|%at|%p']
        if self.config.no_merges:
            log_args.append('--no-merges')

        out = run_git(self.path, log_args)
        commits = []
        if out:
            commits = [l.split('|') for l in out.split('\n') if l]

        self.number_of_commits = len(commits)

        # Check shallow
        shallow = run_git(self.path, ['rev-parse', '--is-shallow-repository'])
        self.is_shallow = (shallow == 'true')

        if commits:
            # Created (first commit)
            first_ts = int(commits[-1][3])
            last_ts = int(commits[0][3])

            dt_first = datetime.datetime.fromtimestamp(first_ts, tz=datetime.timezone.utc)
            dt_last = datetime.datetime.fromtimestamp(last_ts, tz=datetime.timezone.utc)

            if self.config.iso_time:
                self.creation_date = dt_first.strftime("%Y-%m-%dT%H:%M:%SZ")
                self.last_change = dt_last.strftime("%Y-%m-%dT%H:%M:%SZ")
            else:
                self.creation_date = relative_time(dt_first)
                self.last_change = relative_time(dt_last)
        else:
            self.creation_date = ""
            self.last_change = ""

        # Authors statistics
        authors_map = {} # (name, email) -> count
        bot_re = re.compile(self.config.no_bots_regex) if self.config.no_bots else None

        for c in commits:
            aname = c[1]
            aemail = c[2]
            if bot_re and (bot_re.search(aname) or bot_re.search(aemail)):
                continue
            key = (aname, aemail) if self.config.email else (aname, None)
