                    if m: self.version = m.group(1)
                if not self.description:
                    m = re.search(r'description\s*=\s*"([^"]+)"', content)
                    if m: self.description = m.group(1)
                if not self.license:
                    m = re.search(r'license\s*=\s*"([^"]+)"', content)
                    if m: self.license = m.group(1)

