import sys, json, re
from onefetch_data import LANGUAGES_INFO, ASCII_LANGS

def strip_ansi(s):
    return re.sub(r'\x1b\[[0-9;?]*[a-zA-Z]', '', s)

def color_code(code, bold=True):
    if not code:
        return ""
    if not bold:
        return code.replace(";1m", "m")
    return code

def render_json(repo_info):
    cfg = repo_info.config
    dis = cfg.disabled_fields

    info_fields = []

    if 'project' not in dis:
        info_fields.append({
            "ProjectInfo": {
                "repoName": repo_info.repo_name,
                "numberOfBranches": repo_info.number_of_branches,
                "numberOfTags": repo_info.number_of_tags
            }
        })
    if 'description' not in dis:
        info_fields.append({
            "DescriptionInfo": {
                "description": repo_info.description
            }
        })
    if 'head' not in dis:
        info_fields.append({
            "HeadInfo": {
                "headRefs": {
                    "shortCommitId": repo_info.short_commit_id,
                    "refs": repo_info.head_refs
                }
            }
        })
    if 'pending' not in dis:
        info_fields.append({
            "PendingInfo": {
                "added": repo_info.pending_added,
                "deleted": repo_info.pending_deleted,
                "modified": repo_info.pending_modified
            }
        })
    if 'version' not in dis:
        info_fields.append({
            "VersionInfo": {
                "version": repo_info.version
            }
        })
    if 'created' not in dis:
        info_fields.append({
            "CreatedInfo": {
                "creationDate": repo_info.creation_date
            }
        })
    if 'languages' not in dis and repo_info.languages:
        langs_json = []
        for l in repo_info.languages:
            langs_json.append({
                "language": l['json_enum'],
                "percentage": l['percentage']
            })
        info_fields.append({
            "LanguagesInfo": {
                "languagesWithPercentage": langs_json
            }
        })
    if 'dependencies' not in dis:
        info_fields.append({
            "DependenciesInfo": {
                "dependencies": repo_info.dependencies
            }
        })
    if 'authors' not in dis:
        info_fields.append({
            "AuthorsInfo": {
                "authors": repo_info.authors
            }
        })
    if 'last-change' not in dis:
        info_fields.append({
            "LastChangeInfo": {
                "lastChange": repo_info.last_change
            }
        })
    if 'contributors' not in dis:
        info_fields.append({
            "ContributorsInfo": {
                "totalNumberOfAuthors": repo_info.total_authors
            }
        })
    if 'url' not in dis:
        info_fields.append({
            "UrlInfo": {
                "repoUrl": repo_info.repo_url
            }
        })
    if 'commits' not in dis:
        info_fields.append({
            "CommitsInfo": {
                "numberOfCommits": repo_info.number_of_commits,
                "isShallow": repo_info.is_shallow
            }
        })
    if 'churn' not in dis:
        info_fields.append({
            "ChurnInfo": {
                "file_churns": repo_info.file_churns,
                "churn_pool_size": repo_info.churn_pool_size
            }
        })
    if 'lines-of-code' not in dis and repo_info.lines_of_code > 0:
        info_fields.append({
            "LocInfo": {
                "linesOfCode": repo_info.lines_of_code
            }
        })
    if 'size' not in dis:
        info_fields.append({
            "SizeInfo": {
                "repoSize": repo_info.repo_size,
                "fileCount": repo_info.file_count
            }
        })
    if 'license' not in dis:
        info_fields.append({
            "LicenseInfo": {
                "license": repo_info.license
            }
        })

    data = {
        "title": {
            "gitUsername": repo_info.git_username,
            "gitVersion": repo_info.git_version
        },
        "infoFields": info_fields
    }

    return json.dumps(data, indent=2)

def render_yaml(repo_info):
    # Serializes dict to yaml
    def to_yaml(obj, indent=0):
        ind = "  " * indent
        if obj is None:
            return "null"
        elif isinstance(obj, bool):
            return "true" if obj else "false"
        elif isinstance(obj, (int, float)):
            return str(obj)
        elif isinstance(obj, str):
            if obj == "":
                return "''"
            return obj
        elif isinstance(obj, list):
            if not obj:
                return "[]"
            lines = []
            for item in obj:
                if isinstance(item, dict):
                    # List of dicts
                    first = True
                    for k, v in item.items():
                        if first:
                            lines.append(f"{ind}- {k}:")
                            lines.append(to_yaml(v, indent + 2))
                            first = False
                        else:
                            lines.append(f"{ind}  {k}:")
                            lines.append(to_yaml(v, indent + 2))
                else:
                    lines.append(f"{ind}- {to_yaml(item)}")
            return "\n".join(lines)
        elif isinstance(obj, dict):
            lines = []
            for k, v in obj.items():
                if isinstance(v, (dict, list)) and v:
                    lines.append(f"{ind}{k}:")
                    lines.append(to_yaml(v, indent + 1))
                else:
                    lines.append(f"{ind}{k}: {to_yaml(v)}")
            return "\n".join(lines)
        return str(obj)

    json_str = render_json(repo_info)
    data = json.loads(json_str)
    return to_yaml(data)

def render_text(repo_info):
    cfg = repo_info.config
    bold = not cfg.no_bold
    dis = cfg.disabled_fields

    # Determine ASCII language & art lines
    ascii_name = cfg.ascii_language
    if not ascii_name and repo_info.dominant_language:
        ascii_name = repo_info.dominant_language
    if not ascii_name and 'languages' in LANGUAGES_INFO:
        ascii_name = 'text'

    linfo = LANGUAGES_INFO.get(ascii_name, LANGUAGES_INFO.get('text'))
    default_lbl_color = linfo['label_color'] if linfo else '\x1b[34;1m'

    # Text Colors from -t: 1:title, 2:~, 3:underline, 4:subtitle, 5:colon, 6:info
    c_title = color_code(default_lbl_color, bold)
    c_tilde = color_code('\x1b[39;1m', bold)
    c_under = color_code('\x1b[39m', bold)
    c_sub   = color_code(default_lbl_color, bold)
    c_colon = color_code('\x1b[39;1m', bold)
    c_info  = color_code('\x1b[39m', bold)

