import os, sys, subprocess, re, datetime
from onefetch_data import LANGUAGES_INFO, EXT_MAP

def run_git(repo_dir, args):
    cmd = ['git', '-C', repo_dir] + args
    res = subprocess.run(cmd, capture_output=True, text=True)
    if res.returncode != 0:
        return None
    return res.stdout.strip()

def format_size(num_bytes):
    if num_bytes < 1024:
        return f"{num_bytes} B"
    elif num_bytes < 1024 * 1024:
        return f"{num_bytes / 1024:.2f} KiB"
    elif num_bytes < 1024 * 1024 * 1024:
        return f"{num_bytes / (1024 * 1024):.2f} MiB"
    else:
        return f"{num_bytes / (1024 * 1024 * 1024):.2f} GiB"

def relative_time(dt_utc):
    now = datetime.datetime.now(datetime.timezone.utc)
    diff = int((now - dt_utc).total_seconds())
    if diff < 0:
        diff = 0
    if diff < 60:
        return "now"
    minutes = diff // 60
    if minutes < 60:
        return "1 minute ago" if minutes == 1 else f"{minutes} minutes ago"
    hours = minutes // 60
    if hours < 24:
        return "1 hour ago" if hours == 1 else f"{hours} hours ago"
    days = hours // 24
    if days < 14:
        return "1 day ago" if days == 1 else f"{days} days ago"
    weeks = days // 7
    if weeks < 8:
        return "1 week ago" if weeks == 1 else f"{weeks} weeks ago"
    months = days // 30
    if months < 12:
        return "1 month ago" if months == 1 else f"{months} months ago"
    years = days // 365
    return "1 year ago" if years == 1 else f"{years} years ago"

class RepoInfo:
    def __init__(self, config):
        self.config = config
        self.path = os.path.abspath(config.input_path)

        if not os.path.exists(self.path) or not os.path.isdir(self.path):
            sys.stderr.write(f"Error: Failed to access a directory, or path is not a directory: '{config.input_path}'\n")
            sys.exit(1)

        git_dir = run_git(self.path, ['rev-parse', '--git-dir'])
        if git_dir is None:
            sys.stderr.write(f"Error: Could not find a git repository in '{config.input_path}' or in any of its parents\n")
            sys.exit(1)

        head_commit = run_git(self.path, ['rev-parse', 'HEAD'])
        if head_commit is None:
            branch = run_git(self.path, ['symbolic-ref', '--short', 'HEAD']) or 'master'
            sys.stderr.write(f"Error: Failed to traverse Git commit history\n\nCaused by:\n    Branch 'refs/heads/{branch}' does not have any commits\n")
            sys.exit(1)

        self.get_title()
        self.get_project()
        self.get_head()
        self.get_pending()
        self.get_commits_and_authors()
        self.get_churn()
        self.get_url()
        self.get_package_and_license()
        self.get_size_and_filecount()
        self.get_languages_and_loc()

    def get_title(self):
        uname = run_git(self.path, ['config', 'user.name'])
        if not uname:
            uname = run_git(self.path, ['config', 'user.email'])
        self.git_username = uname or ""

        gver = run_git(self.path, ['--version']) or "git version 2.34.1"
        self.git_version = gver

    def get_project(self):
        url = run_git(self.path, ['config', '--get', 'remote.origin.url']) or ""
        repo_name = ""
        if url:
            m = re.search(r'[:/]([^/]+?)(?:\.git)?$', url)
            if m:
                repo_name = m.group(1)
        self.repo_name = repo_name

        remotes = run_git(self.path, ['for-each-ref', '--format=%(refname)', 'refs/remotes/'])
        num_branches = 0
        if remotes:
            lines = [r for r in remotes.split('\n') if r and not r.endswith('/HEAD')]
            num_branches = len(lines)
        self.number_of_branches = num_branches

        tags = run_git(self.path, ['tag'])
        num_tags = len(tags.split('\n')) if tags else 0
        self.number_of_tags = num_tags

    def get_head(self):
        short_id = run_git(self.path, ['rev-parse', '--short', 'HEAD']) or ""
        self.short_commit_id = short_id

        refs_raw = run_git(self.path, ['for-each-ref', '--points-at=HEAD', '--format=%(refname:short)'])
        refs = []
        if refs_raw:
            refs = [r for r in refs_raw.split('\n') if r and not r.startswith('origin/')]
        if not refs:
            branch = run_git(self.path, ['rev-parse', '--abbrev-ref', 'HEAD'])
            if branch and branch != 'HEAD':
                refs = [branch]
        self.head_refs = refs

    def get_pending(self):
        status = run_git(self.path, ['status', '--porcelain'])
        added = 0
        deleted = 0
        modified = 0
        if status:
            for line in status.split('\n'):
                if not line: continue
                st = line[:2]
                if '?' in st or 'A' in st:
                    added += 1
                elif 'D' in st:
                    deleted += 1
                elif 'M' in st or 'R' in st:
                    modified += 1
        self.pending_added = added
        self.pending_deleted = deleted
        self.pending_modified = modified

    def get_commits_and_authors(self):
        log_args = ['log', '--format=%H|%an|%ae|%at|%p']
        if self.config.no_merges:
            log_args.append('--no-merges')

        out = run_git(self.path, log_args)
        commits = []
        if out:
            commits = [l.split('|') for l in out.split('\n') if l]

        self.number_of_commits = len(commits)

        shallow = run_git(self.path, ['rev-parse', '--is-shallow-repository'])
        self.is_shallow = (shallow == 'true')

        if commits:
            first_ts = int(commits[-1][3])
            last_ts = int(commits[0][3])

            dt_first = datetime.datetime.fromtimestamp(first_ts, tz=datetime.timezone.utc)
            dt_last = datetime.datetime.fromtimestamp(last_ts, tz=datetime.timezone.utc)

            if self.config.iso_time:
                self.creation_date = dt_first.strftime("%Y-%m-%dT%H:%M:%SZ")
                self.last_change = dt_last.strftime("%Y-%m-%dT%H:%M:%SZ")
            else:
                self.creation_date = relative_time(dt_first)
                self.last_change = relative_time(dt_last)
        else:
            self.creation_date = ""
            self.last_change = ""

        authors_map = {}
        bot_re = re.compile(self.config.no_bots_regex) if self.config.no_bots else None

        for c in commits:
            aname = c[1]
            aemail = c[2]
            if bot_re and (bot_re.search(aname) or bot_re.search(aemail)):
                continue
            key = (aname, aemail) if self.config.email else (aname, None)
            authors_map[key] = authors_map.get(key, 0) + 1

        self.total_authors = len(authors_map)

        sorted_auth = sorted(authors_map.items(), key=lambda x: x[1], reverse=True)
        tot_commits = sum(authors_map.values()) if authors_map else 1

        authors_list = []
        for (aname, aemail), count in sorted_auth[:self.config.number_of_authors]:
            contrib = round(100.0 * count / tot_commits)
            authors_list.append({
                'name': aname,
                'email': aemail,
                'nbrOfCommits': count,
                'contribution': int(contrib)
            })
        self.authors = authors_list

    def get_churn(self):
        pool_size = self.config.churn_pool_size
        if pool_size is None:
            two_weeks_ago = int((datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(days=14)).timestamp())
            log_out = run_git(self.path, ['log', f'--since={two_weeks_ago}', '--format=%H'])
            if log_out:
                pool_size = len([l for l in log_out.split('\n') if l])
            else:
                pool_size = 1
        if pool_size < 1:
            pool_size = 1

        self.churn_pool_size = pool_size

        num_str = f"-n{pool_size}"
        out = run_git(self.path, ['log', num_str, '--name-only', '--format='])
        file_counts = {}
        if out:
            for line in out.split('\n'):
                line = line.strip()
                if line:
                    file_counts[line] = file_counts.get(line, 0) + 1

        sorted_files = sorted(file_counts.items(), key=lambda x: x[1], reverse=True)
        file_churns = []
        for fpath, cnt in sorted_files[:self.config.number_of_file_churns]:
            file_churns.append({
                'filePath': fpath,
                'nbrOfCommits': cnt
            })
        self.file_churns = file_churns

    def get_url(self):
        url = run_git(self.path, ['config', '--get', 'remote.origin.url']) or ""
        if url:
            if self.config.http_url:
                if url.startswith('git@'):
                    url = re.sub(r'^git@([^:]+):', r'https://\1/', url)
                elif url.startswith('ssh://git@'):
                    url = re.sub(r'^ssh://git@', 'https://', url)

            if self.config.hide_token:
                url = re.sub(r'https?://[^@]+@', 'https://', url)
            else:
                url = re.sub(r'(https?://[^:]+:)[^@]+@', r'\1redacted@', url)

        self.repo_url = url

    def get_package_and_license(self):
        self.version = ""
        self.description = None
        self.license = ""
        self.dependencies = ""

        tag = run_git(self.path, ['describe', '--tags', '--abbrev=0'])
        if tag:
            self.version = tag

        cargo_path = os.path.join(self.path, 'Cargo.toml')
        pkg_json_path = os.path.join(self.path, 'package.json')

        if os.path.exists(cargo_path):
            try:
                with open(cargo_path, 'r', encoding='utf-8', errors='ignore') as f:
                    content = f.read()
                if not self.version:
                    m = re.search(r'version\s*=\s*"([^"]+)"', content)
                    if m: self.version = m.group(1)
                if not self.description:
                    m = re.search(r'description\s*=\s*"([^"]+)"', content)
                    if m: self.description = m.group(1)
                if not self.license:
                    m = re.search(r'license\s*=\s*"([^"]+)"', content)
                    if m: self.license = m.group(1)

                m_deps = re.search(r'\[dependencies\]\n(.*?)(?:\n\[|$)', content, re.DOTALL)
                if m_deps:
                    dep_lines = [l for l in m_deps.group(1).split('\n') if l.strip() and not l.strip().startswith('#') and '=' in l]
                    if dep_lines:
                        self.dependencies = f"{len(dep_lines)} (Cargo)"
            except:
                pass

        elif os.path.exists(pkg_json_path):
            try:
                import json
                with open(pkg_json_path, 'r', encoding='utf-8', errors='ignore') as f:
                    d = json.load(f)
                if not self.version and 'version' in d:
                    self.version = d['version']
                if not self.description and 'description' in d:
                    self.description = d['description']
                if not self.license and 'license' in d:
                    self.license = d['license']
                if 'dependencies' in d and isinstance(d['dependencies'], dict):
                    cnt = len(d['dependencies'])
                    if cnt > 0:
                        self.dependencies = f"{cnt} (Npm)"
            except:
                pass

        if not self.license:
            for fname in os.listdir(self.path):
                if fname.lower().startswith('license') or fname.lower().startswith('licence'):
                    lic_f = os.path.join(self.path, fname)
                    if os.path.isfile(lic_f):
                        try:
                            with open(lic_f, 'r', encoding='utf-8', errors='ignore') as f:
                                head = f.read(1000)
                            if 'MIT' in head: self.license = 'MIT'
                            elif 'Apache' in head: self.license = 'Apache-2.0'
                            elif 'GPL' in head: self.license = 'GPL'
                            elif 'BSD' in head: self.license = 'BSD'
                            else: self.license = fname
                        except:
                            pass
                    break

    def get_size_and_filecount(self):
        # Count tracked files
        ls_out = run_git(self.path, ['ls-files'])
        files = []
        if ls_out:
            files = [f for f in ls_out.split('\n') if f]

        tot_size = 0
        tot_count = 0
        for frel in files:
            if not self.config.include_hidden and frel.startswith('.'):
                continue
            fp = os.path.join(self.path, frel)
            if os.path.isfile(fp):
                try:
                    tot_size += os.path.getsize(fp)
                    tot_count += 1
                except:
                    pass
        self.repo_size = format_size(tot_size)
        self.file_count = tot_count

    def get_languages_and_loc(self):
        # Scan working tree files for LOC & languages
        ls_files_out = run_git(self.path, ['ls-files', '--cached', '--others', '--exclude-standard'])
        files = []
        if ls_files_out:
            files = [f for f in ls_files_out.split('\n') if f]

        # Exclude patterns
        if self.config.exclude:
            filtered = []
            for f in files:
                excl = False
                for pattern in self.config.exclude:
                    if pattern in f:
                        excl = True; break
                if not excl:
                    filtered.append(f)
            files = filtered

